import React, { useState } from "react";
import { useBookContext } from "../contexts/BookContext";


function AddBookForm() {
  const [olid, setOlid] = useState("");
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);


  const { addBook } = useBookContext();

  // function for form submission
  async function handleSubmit(e: React.FormEvent) {
    e.preventDefault(); 
    if (!olid.trim()) return; 

    setIsLoading(true);
    setError(null);
    try {
      const result = await addBook(olid.trim()); 
      if (result && result.success) {
        setOlid(""); 
      } else {
        setError(result?.message || "Error adding book. Please try again.");
      }
    } catch (error) {
      console.error("ERROR ADDING BOOK:", error);
      setError("An unexpected error occurred.");
    } finally {
      setIsLoading(false);
    }
  }

  return (
    <div className="mb-8 p-6 border border-amber-200 rounded-lg bg-amber-100/50 shadow-sm">
      <h3 className="mb-4 text-xl font-semibold text-amber-800">Add a Book</h3>
      <form onSubmit={handleSubmit} className="space-y-4">
        <div>
          <label htmlFor="olid" className="block mb-2 text-sm font-medium text-amber-700">
            Please enter Open Library ID:
          </label>
          <div className="relative">
            <div className="absolute inset-y-0 left-0 flex items-center pl-3 pointer-events-none">
              <svg className="w-4 h-4 text-amber-500" aria-hidden="true" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 20 20">
                <path stroke="currentColor" strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="m19 19-4-4m0-7A7 7 0 1 1 1 8a7 7 0 0 1 14 0Z"/>
              </svg>
            </div>
            <input
              type="text"
              id="olid"
              value={olid}
              onChange={(e) => setOlid(e.target.value)}
              placeholder="Enter OLID (e.g., OL7353617M)"
              className="bg-amber-50 border border-amber-300 text-amber-900 text-sm rounded-lg focus:ring-amber-500 focus:border-amber-500 block w-full pl-10 p-2.5"
              disabled={isLoading}
            />
          </div>
          <p className="mt-1 text-sm text-amber-600">Enter the Open Library ID to fetch book details</p>
        </div>
        
        {error && (
          <div className="p-4 mb-4 text-sm text-red-800 rounded-lg bg-red-50 border border-red-200" role="alert">
            <span className="font-medium">Error!</span> {error}
          </div>
        )}
        
        <button
          type="submit"
          disabled={isLoading}
          className={`text-white focus:ring-4 focus:outline-none font-medium rounded-lg text-sm px-5 py-2.5 text-center inline-flex items-center ${isLoading ? 'bg-amber-400 cursor-not-allowed' : 'bg-amber-600 hover:bg-amber-700 focus:ring-amber-300'}`}
        >
          {isLoading ? (
            <>
              <svg aria-hidden="true" role="status" className="inline w-4 h-4 mr-3 text-white animate-spin" viewBox="0 0 100 101" fill="none" xmlns="http://www.w3.org/2000/svg">
                <path d="M100 50.5908C100 78.2051 77.6142 100.591 50 100.591C22.3858 100.591 0 78.2051 0 50.5908C0 22.9766 22.3858 0.59082 50 0.59082C77.6142 0.59082 100 22.9766 100 50.5908ZM9.08144 50.5908C9.08144 73.1895 27.4013 91.5094 50 91.5094C72.5987 91.5094 90.9186 73.1895 90.9186 50.5908C90.9186 27.9921 72.5987 9.67226 50 9.67226C27.4013 9.67226 9.08144 27.9921 9.08144 50.5908Z" fill="#E5E7EB"/>
                <path d="M93.9676 39.0409C96.393 38.4038 97.8624 35.9116 97.0079 33.5539C95.2932 28.8227 92.871 24.3692 89.8167 20.348C85.8452 15.1192 80.8826 10.7238 75.2124 7.41289C69.5422 4.10194 63.2754 1.94025 56.7698 1.05124C51.7666 0.367541 46.6976 0.446843 41.7345 1.27873C39.2613 1.69328 37.813 4.19778 38.4501 6.62326C39.0873 9.04874 41.5694 10.4717 44.0505 10.1071C47.8511 9.54855 51.7191 9.52689 55.5402 10.0491C60.8642 10.7766 65.9928 12.5457 70.6331 15.2552C75.2735 17.9648 79.3347 21.5619 82.5849 25.841C84.9175 28.9121 86.7997 32.2913 88.1811 35.8758C89.083 38.2158 91.5421 39.6781 93.9676 39.0409Z" fill="currentColor"/>
              </svg>
              Adding...
            </>
          ) : (
            <>
              Add Book
              <svg className="w-3.5 h-3.5 ml-2" aria-hidden="true" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 14 10">
                <path stroke="currentColor" strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M1 5h12m0 0L9 1m4 4L9 9"/>
              </svg>
            </>
          )}
        </button>
      </form>
    </div>
  );
}

export default AddBookForm;
